<?php
namespace App\Console\Commands;
use App\Models\User; use Illuminate\Console\Command; use Illuminate\Support\Facades\Hash;
class CreatePchatAdmin extends Command { protected $signature='pchat:create-admin {--name=} {--email=}'; protected $description='Create or promote a PCHAT administrator securely.'; public function handle(): int { $name=$this->option('name') ?: $this->ask('Name'); $email=$this->option('email') ?: $this->ask('Email'); $password=$this->secret('Password (leave blank to promote an existing account)'); $user=User::where('email',$email)->first(); if(!$user && blank($password)){ $this->error('A password is required for a new account.'); return self::FAILURE; } $user ? $user->update(['role'=>'admin','status'=>'active']) : User::create(['name'=>$name,'username'=>strtolower(str($email)->before('@')).'-admin','email'=>$email,'password'=>Hash::make($password),'role'=>'admin','status'=>'active']); $this->info('Administrator ready.'); return self::SUCCESS; } }
